// -- Flags ----------------------------------------------------------------

/// Groups of events, for choosing which ones an instance queues. An event's class is the high
/// byte of its type: the bit for it is 1 << (type >> 8).
pub type WGUIEventClass = WGUIFlags;
pub const WGUIEventClass_None: WGUIEventClass = 0x0000000000000000;
/// Lost events and completed requests. Always on.
pub const WGUIEventClass_System: WGUIEventClass = 0x0000000000000002;
pub const WGUIEventClass_Application: WGUIEventClass = 0x0000000000000004;
pub const WGUIEventClass_Display: WGUIEventClass = 0x0000000000000008;
pub const WGUIEventClass_Window: WGUIEventClass = 0x0000000000000010;
pub const WGUIEventClass_Keyboard: WGUIEventClass = 0x0000000000000020;
pub const WGUIEventClass_Text: WGUIEventClass = 0x0000000000000040;
pub const WGUIEventClass_Pointer: WGUIEventClass = 0x0000000000000080;
pub const WGUIEventClass_Wheel: WGUIEventClass = 0x0000000000000100;
/// Device input before the window system shapes it. Off unless asked for.
pub const WGUIEventClass_Raw: WGUIEventClass = 0x0000000000000200;
/// Reserved.
pub const WGUIEventClass_Gesture: WGUIEventClass = 0x0000000000000400;
pub const WGUIEventClass_Clipboard: WGUIEventClass = 0x0000000000000800;
/// Reserved.
pub const WGUIEventClass_Drop: WGUIEventClass = 0x0000000000001000;
/// Reserved.
pub const WGUIEventClass_Device: WGUIEventClass = 0x0000000000002000;
/// Reserved.
pub const WGUIEventClass_Gamepad: WGUIEventClass = 0x0000000000004000;
/// What WGUI_INSTANCE_DESCRIPTOR_INIT asks for.
pub const WGUIEventClass_Default: WGUIEventClass = 0x00000000000009FE;

/// A window's state. The low 16 bits can be asked for (at creation and with
/// wguiWindowSetFlags); the rest are only reported.
pub type WGUIWindowFlags = WGUIFlags;
pub const WGUIWindowFlags_None: WGUIWindowFlags = 0x0000000000000000;
/// Shown on screen.
pub const WGUIWindowFlags_Visible: WGUIWindowFlags = 0x0000000000000001;
/// The user can resize it.
pub const WGUIWindowFlags_Resizable: WGUIWindowFlags = 0x0000000000000002;
/// It has a title bar and borders.
pub const WGUIWindowFlags_Decorated: WGUIWindowFlags = 0x0000000000000004;
pub const WGUIWindowFlags_Minimized: WGUIWindowFlags = 0x0000000000000008;
pub const WGUIWindowFlags_Maximized: WGUIWindowFlags = 0x0000000000000010;
pub const WGUIWindowFlags_AlwaysOnTop: WGUIWindowFlags = 0x0000000000000020;
pub const WGUIWindowFlags_AlwaysOnBottom: WGUIWindowFlags = 0x0000000000000040;
/// The window's background can show what is behind it. Only at creation.
pub const WGUIWindowFlags_Transparent: WGUIWindowFlags = 0x0000000000000080;
/// Every bit a program can ask for.
pub const WGUIWindowFlags_Requestable: WGUIWindowFlags = 0x000000000000FFFF;
/// It has keyboard focus. Changes are announced by WGUIEventType_WindowFocusGained and
/// WindowFocusLost, not by WindowFlagsChanged.
pub const WGUIWindowFlags_Focused: WGUIWindowFlags = 0x0000000000010000;
/// The mouse cursor is over it. Changes are announced by the mouse's WGUIEventType_PointerEnter
/// and PointerLeave.
pub const WGUIWindowFlags_Hovered: WGUIWindowFlags = 0x0000000000020000;
/// Nothing of it can be seen: drawing is wasted.
pub const WGUIWindowFlags_Occluded: WGUIWindowFlags = 0x0000000000040000;
/// Changed with wguiWindowSetFullscreen.
pub const WGUIWindowFlags_Fullscreen: WGUIWindowFlags = 0x0000000000080000;

/// How to read a WGUIWindowDescriptor.
pub type WGUIWindowOptions = u32;
pub const WGUIWindowOptions_None: WGUIWindowOptions = 0x00000000;
/// The descriptor's sizes, limits and position are in logical units: the host multiplies them
/// by the scale factor of the display the window opens on, which the program cannot know yet.
pub const WGUIWindowOptions_LogicalUnits: WGUIWindowOptions = 0x00000001;
/// Place the window at the descriptor's x and y.
pub const WGUIWindowOptions_Positioned: WGUIWindowOptions = 0x00000002;

pub type WGUIFullscreenFlags = u32;
pub const WGUIFullscreenFlags_None: WGUIFullscreenFlags = 0x00000000;
/// Fail with WGUIStatus_Denied instead of waiting for a user gesture.
pub const WGUIFullscreenFlags_NoDeferral: WGUIFullscreenFlags = 0x00000001;

/// Why wguiInstanceWaitEvents returned. None of them: the timeout passed.
pub type WGUIWaitReasons = u32;
pub const WGUIWaitReasons_None: WGUIWaitReasons = 0x00000000;
/// The queue has records.
pub const WGUIWaitReasons_Events: WGUIWaitReasons = 0x00000001;
/// The instance was woken: wguiInstanceWake was called, or the host has other work for the
/// program (a WebGPU event, say). Look at what else the program waits for.
pub const WGUIWaitReasons_Woken: WGUIWaitReasons = 0x00000002;
/// The host ended the wait so that the system can reach the thread. Nothing happened; wait
/// again.
pub const WGUIWaitReasons_Interrupted: WGUIWaitReasons = 0x00000004;

pub type WGUIEventFlags = u32;
pub const WGUIEventFlags_None: WGUIEventFlags = 0x00000000;
/// Made by the host to keep the program's view consistent (a key release on focus loss), not
/// caused by the user just now.
pub const WGUIEventFlags_Synthetic: WGUIEventFlags = 0x00000001;
/// Stands for several events of the same kind that the host merged.
pub const WGUIEventFlags_Coalesced: WGUIEventFlags = 0x00000002;
/// Only on WindowRedrawRequested, with WGUIFeatureName_RedrawReasons: it answers
/// wguiWindowRequestRedraw. A time to draw; on its own it does not mean that what the window
/// showed is gone. Exposure may be set too.
pub const WGUIEventFlags_FrameCallback: WGUIEventFlags = 0x00000004;
/// Only on WindowRedrawRequested, with WGUIFeatureName_RedrawReasons: the window has to be
/// shown whole again. So is the first redraw of a window, the first after its size changed, and
/// one when it becomes visible again. A merged redraw keeps it.
pub const WGUIEventFlags_Exposure: WGUIEventFlags = 0x00000008;

/// What a WGUIEventType_WindowResized changed.
pub type WGUIResizeFlags = u32;
pub const WGUIResizeFlags_None: WGUIResizeFlags = 0x00000000;
pub const WGUIResizeFlags_Size: WGUIResizeFlags = 0x00000001;
pub const WGUIResizeFlags_ScaleFactor: WGUIResizeFlags = 0x00000002;

