// -- Keys -----------------------------------------------------------------

/// What a key means on the user's layout: the KeyboardEvent `key` of the W3C UI Events
/// specification, as a number. The top byte is a tag (WGUI_KEY_TAG) and the rest its value
/// (WGUI_KEY_VALUE):
///
/// WGUI_KEY_CHARACTER: the Unicode scalar value the key produces, so 'a' is 0x61. 0 is
/// WGUIKey_Unidentified.
///
/// WGUI_KEY_NAMED: one of the WGUIKey_* constants below.
///
/// WGUI_KEY_DEAD: a dead key; the value is the combining character it adds, or 0.
///
/// WGUI_KEY_SEQUENCE: more than one scalar value; the value is the first and the event's
/// keyString has all.
pub type WGUIKey = u32;

pub const fn WGUI_KEY_TAG(key: WGUIKey) -> u32 {
    key & WGUI_KEY_TAG_MASK
}

pub const fn WGUI_KEY_VALUE(key: WGUIKey) -> u32 {
    key & WGUI_KEY_VALUE_MASK
}

