// -- Event records --------------------------------------------------------

/// What every event record starts with. Records are little-endian, 8-byte aligned, and say how
/// long they are: a record a program does not know, or one longer than it expects, is stepped
/// over by its size.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIEventHeader {
    /// The whole record in bytes, strings and padding included; a multiple of 8. The next
    /// record starts this far on.
    pub size: u32,
    pub r#type: WGUIEventType,
    pub flags: WGUIEventFlags,
    /// The window the event is for, or 0.
    pub window: WGUIWindow,
    /// When it happened, in nanoseconds on the clock of wguiInstanceGetTime. Never decreases
    /// from one record to the next.
    pub timestamp: u64,
    /// Which piece of hardware, where the host can tell them apart; 0 otherwise.
    pub device: u32,
    /// Counts the records this instance has been given.
    pub sequence: u32,
}

/// A string inside an event record: `length` bytes of UTF-8 starting `offset` bytes from the
/// start of the record. An offset of 0 means there is no string. See wguiEventGetString.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIEventString {
    pub offset: u32,
    pub length: u32,
}

/// The queue overflowed and records were dropped. What follows makes the program's view right
/// again: releases for keys and buttons it believes held, and each window's current size and
/// flags. Dropped text is gone.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIEventsLostEvent {
    pub header: WGUIEventHeader,
    /// How many records were dropped.
    pub count: u32,
    pub reserved: u32,
    /// The classes they belonged to.
    pub classes: WGUIEventClass,
}

/// A request made with a tag is over. Every accepted request gets exactly one, also when its
/// window is destroyed first.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIRequestCompletedEvent {
    pub header: WGUIEventHeader,
    /// The tag the program passed.
    pub tag: u64,
    pub kind: WGUIRequestKind,
    pub status: WGUIStatus,
}

