/// A key went down or up.
///
/// Per window, downs and ups pair up: no release arrives for a press the window did not get. A
/// held key repeats as further downs flagged Repeat. Before a window loses focus it gets a
/// synthetic release for every key still down.
///
/// `text` is what the press types through the keyboard layout, with or without text input on.
/// While text input is on, the same text also arrives as a WGUIEventType_TextCommit flagged
/// FromKey.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIKeyEvent {
    pub header: WGUIEventHeader,
    /// Which key, wherever the layout puts its letters.
    pub physicalKey: WGUIPhysicalKey,
    /// The platform's own code for the key, for keys physicalKey cannot name. 0 if unknown.
    pub nativeScancode: u32,
    /// What the key means with the modifiers held, Control aside.
    pub key: WGUIKey,
    /// What it means with no modifier held: the layout's base layer. 0 if unknown.
    pub keyUnmodified: WGUIKey,
    /// The modifiers after this event.
    pub modifiers: WGUIModifiers,
    pub keyFlags: WGUIKeyFlags,
    pub location: WGUIKeyLocation,
    pub reserved: u32,
    /// `key` as text when it is a character, a dead key or a sequence.
    pub keyString: WGUIEventString,
    /// The text this press types. Absent for releases and for keys that type nothing.
    pub text: WGUIEventString,
    /// The same with Control applied too, as terminals want it (Control+C is U+0003).
    pub textWithAllModifiers: WGUIEventString,
}

/// The modifiers changed. Follows the key event that caused it, and focus gained when some are
/// already held.
#[repr(C)]
#[derive(Clone, Copy, Debug)]
