#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIRawButtonEvent {
    pub header: WGUIEventHeader,
    pub button: WGUIPointerButton,
    pub pressed: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIRawWheelEvent {
    pub header: WGUIEventHeader,
    pub unit: WGUIWheelUnit,
    pub reserved: u32,
    pub deltaX: f64,
    pub deltaY: f64,
}

#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIRawKeyEvent {
    pub header: WGUIEventHeader,
    pub physicalKey: WGUIPhysicalKey,
    pub nativeScancode: u32,
    pub pressed: u32,
    pub reserved: u32,
}

#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct WGUIClipboardChangedEvent {
    pub header: WGUIEventHeader,
    pub selection: WGUIClipboardSelection,
    pub clipboardFlags: WGUIClipboardFlags,
    pub clipboardSequence: u32,
    pub reserved: u32,
}

// -- Functions ------------------------------------------------------------

#[cfg_attr(target_family = "wasm", link(wasm_import_module = "wasmer_gui_v0"))]
extern "C" {
    // Global

    /// The newest version of this API the host implements, as major << 16 | minor. 0 means the
    /// host has no such function (it is older than every version).
    pub fn wguiGetVersion() -> u32;

    /// Whether this program may use a feature here: the host can do it and the embedder allows
    /// it.
    pub fn wguiHasFeature(feature: WGUIFeatureName) -> WGUIBool;

    /// Lists the features wguiHasFeature would confirm. Writes up to `capacity` of them and
    /// sets `count` to how many there are.
    pub fn wguiGetFeatures(capacity: usize, features: *mut WGUIFeatureName, count: *mut usize) -> WGUIStatus;

    /// Connects to the window system. NULL is WGUI_INSTANCE_DESCRIPTOR_INIT. Fails with
    /// WGUIStatus_Unsupported when a required feature is missing.
    pub fn wguiCreateInstance(descriptor: *const WGUIInstanceDescriptor, instance: *mut WGUIInstance) -> WGUIStatus;

    // WGUIInstance

    /// Destroys the instance with everything created on it. Requests still pending complete as
    /// WGUIStatus_Cancelled and are then dropped with the queue.
    pub fn wguiInstanceDestroy(instance: WGUIInstance);

    /// What kind of host this is and what it has.
    pub fn wguiInstanceGetInfo(instance: WGUIInstance, info: *mut WGUIInstanceInfo) -> WGUIStatus;

    /// Copies queued event records into `buffer`, oldest first, as many whole records as fit,
    /// and sets `written` to their total size (0 when the queue is empty). Never blocks.
    ///
    /// `buffer` must be 8-byte aligned and `capacity` at least WGUI_MAX_EVENT_SIZE, so one
    /// record always fits. Step through the records with wguiEventFirst and wguiEventNext.
    ///
    /// This call and wguiInstanceWaitEvents are also where signals reach the program. A WASIX
    /// runtime delivers them where a program enters the system, and a program that draws frame
    /// after frame may do that nowhere else, so the host lets them in here: a handler the
    /// program installed runs before the call returns, and a signal that ends the program ends
    /// it in this call.
    pub fn wguiInstancePollEvents(instance: WGUIInstance, buffer: *mut core::ffi::c_void, capacity: usize, written: *mut usize) -> WGUIStatus;

    /// Blocks until the queue has a record, the instance is woken, or `timeout` nanoseconds
    /// pass (0 only checks; WGUI_WAIT_FOREVER never times out). `reasons` says why it returned;
    /// 0 is a timeout.
    ///
    /// The instance is woken by wguiInstanceWake, or by the host when it has other work for the
    /// program, such as a WebGPU event that became ready. A wake that happened before the wait
    /// is not lost: it ends the next wait. Signals reach the program as this call returns, not
    /// while it sleeps in it (see wguiInstancePollEvents). So that they are not kept waiting,
    /// the host ends a long wait early with WGUIWaitReasons_Interrupted: unless a signal
    /// handler did something, nothing happened, and the program waits again.
    ///
    /// May block.
    pub fn wguiInstanceWaitEvents(instance: WGUIInstance, timeout: u64, reasons: *mut WGUIWaitReasons) -> WGUIStatus;

    /// Ends the current wguiInstanceWaitEvents of this instance, or the next one if none is
    /// waiting. For waking a program's event loop from another thread.
    pub fn wguiInstanceWake(instance: WGUIInstance) -> WGUIStatus;

    /// Chooses which classes of events are queued from now on. Records already queued stay.
    /// WGUIEventClass_System cannot be turned off.
    pub fn wguiInstanceSetEventMask(instance: WGUIInstance, mask: WGUIEventClass) -> WGUIStatus;

    /// The current time on the clock event timestamps use, in nanoseconds. Hosts make it the
    /// WASI monotonic clock where they can.
    pub fn wguiInstanceGetTime(instance: WGUIInstance, time: *mut u64) -> WGUIStatus;

    /// Lists the displays, the primary one first. Writes up to `capacity` handles and sets
    /// `count` to how many there are. Display handles stay valid until
    /// WGUIEventType_DisplaysChanged says the set changed.
    pub fn wguiInstanceGetDisplays(instance: WGUIInstance, capacity: usize, displays: *mut WGUIDisplay, count: *mut usize) -> WGUIStatus;

    /// Opens a window, or adopts the target the descriptor names. NULL asks for the host's
    /// default window.
    ///
    /// The first record queued for the new window is a WGUIEventType_WindowResized with its
    /// real size and scale factor.
    ///
    /// May block.
    pub fn wguiInstanceCreateWindow(instance: WGUIInstance, descriptor: *const WGUIWindowDescriptor, window: *mut WGUIWindow) -> WGUIStatus;

    /// Makes a cursor from an image, for wguiWindowSetCustomCursor.
    pub fn wguiInstanceCreateCursor(instance: WGUIInstance, descriptor: *const WGUICursorDescriptor, cursor: *mut WGUICursor) -> WGUIStatus;

    /// What the host knows about a clipboard right now, without reading it.
    pub fn wguiInstanceGetClipboardInfo(instance: WGUIInstance, selection: WGUIClipboardSelection, info: *mut WGUIClipboardInfo) -> WGUIStatus;

    /// Copies the clipboard's content of one MIME type into `buffer` and sets `size` to its
    /// length in bytes. Text is "text/plain", UTF-8, not NUL-terminated.
    ///
    /// WGUIStatus_BufferTooSmall: `size` holds what is needed, nothing was copied.
    /// WGUIStatus_Pending: the host cannot answer without asking the system first (a browser);
    /// call wguiInstanceRequestClipboard and read again once it completes. WGUIStatus_NotFound:
    /// nothing of that type. WGUIStatus_Denied: the program may not read the clipboard.
    pub fn wguiInstanceReadClipboard(instance: WGUIInstance, selection: WGUIClipboardSelection, mimeType: *const u8, mimeTypeLength: usize, buffer: *mut core::ffi::c_void, capacity: usize, size: *mut usize) -> WGUIStatus;

    /// Asks the host to fetch the clipboard's content of one MIME type, so that
    /// wguiInstanceReadClipboard can answer. Completes with WGUIEventType_RequestCompleted
    /// carrying `tag`: Success, Denied or NotFound.
    pub fn wguiInstanceRequestClipboard(instance: WGUIInstance, selection: WGUIClipboardSelection, mimeType: *const u8, mimeTypeLength: usize, tag: u64) -> WGUIStatus;

    /// Replaces the clipboard's content with these items (one per MIME type; none clears it).
    /// The program's own reads see the new content at once; WGUIEventType_RequestCompleted with
    /// `tag` says whether the system took it.
    pub fn wguiInstanceWriteClipboard(instance: WGUIInstance, selection: WGUIClipboardSelection, itemCount: usize, items: *const WGUIClipboardItem, tag: u64) -> WGUIStatus;

    // WGUIDisplay

    /// The display's geometry, scale factor and refresh rate.
    pub fn wguiDisplayGetInfo(display: WGUIDisplay, info: *mut WGUIDisplayInfo) -> WGUIStatus;

    /// The display's name for people, UTF-8, not NUL-terminated. Copies up to `capacity` bytes
    /// and sets `length` to the name's full length.
    pub fn wguiDisplayGetName(display: WGUIDisplay, buffer: *mut u8, capacity: usize, length: *mut usize) -> WGUIStatus;

    // WGUIWindow

    /// Closes the window. No more records are queued for it; ones already queued can still be
    /// read. A WebGPU surface created on it keeps presenting nowhere until it is released.
    pub fn wguiWindowDestroy(window: WGUIWindow);

    /// The window's current size, scale factor, position and flags. Answered from what the host
    /// last saw, without waiting for the window system.
    pub fn wguiWindowGetState(window: WGUIWindow, state: *mut WGUIWindowState) -> WGUIStatus;

    /// The name to draw on this window with WebGPU: put it in
    /// WGPUWasixSurfaceSourceCanvas.selector. UTF-8, not NUL-terminated. Copies up to
    /// `capacity` bytes and sets `length` to the full length.
    ///
    /// For a window that adopted a named target this is that name; otherwise the host makes one
    /// up, starting with "wgui:".
    pub fn wguiWindowGetSurfaceSelector(window: WGUIWindow, buffer: *mut u8, capacity: usize, length: *mut usize) -> WGUIStatus;

    /// Sets the window's title.
    pub fn wguiWindowSetTitle(window: WGUIWindow, title: *const u8, titleLength: usize) -> WGUIStatus;

    /// Asks for a new size of the content area. The size the window ends up with arrives as
    /// WGUIEventType_WindowResized; WGUIStatus_Unsupported when the embedder decides the size.
    pub fn wguiWindowSetSize(window: WGUIWindow, width: u32, height: u32) -> WGUIStatus;

    /// Limits how small and how large the user can make the content area. 0 means no limit.
    pub fn wguiWindowSetSizeLimits(window: WGUIWindow, minWidth: u32, minHeight: u32, maxWidth: u32, maxHeight: u32) -> WGUIStatus;

    /// Moves the window's content area to a position on the desktop. Needs
    /// WGUIFeatureName_WindowPosition.
    pub fn wguiWindowSetPosition(window: WGUIWindow, x: i32, y: i32) -> WGUIStatus;

    /// Changes the flags in `mask` to their bits in `values`: show or hide, minimize, maximize,
    /// restore, borders, level. What actually happened arrives as
    /// WGUIEventType_WindowFlagsChanged. `unsupported` receives the bits of `mask` this host
    /// cannot change.
    pub fn wguiWindowSetFlags(window: WGUIWindow, mask: WGUIWindowFlags, values: WGUIWindowFlags, unsupported: *mut WGUIWindowFlags) -> WGUIStatus;

    /// Enters fullscreen as `options` says, or leaves it when `options` is NULL. Completes with
    /// WGUIEventType_RequestCompleted carrying `tag`. Where the platform insists on a user
    /// gesture (a browser), the request waits for the next one unless the options forbid
    /// waiting.
    ///
    /// The user can leave fullscreen without the program asking;
    /// WGUIEventType_WindowFlagsChanged reports every change.
    pub fn wguiWindowSetFullscreen(window: WGUIWindow, options: *const WGUIFullscreenOptions, tag: u64) -> WGUIStatus;

    /// Asks for keyboard focus and brings the window forward. Window systems may refuse.
    pub fn wguiWindowFocus(window: WGUIWindow) -> WGUIStatus;

    /// Asks for the user's attention without taking focus (a bouncing icon, a flashing task bar
    /// entry).
    pub fn wguiWindowRequestAttention(window: WGUIWindow, level: WGUIAttentionLevel) -> WGUIStatus;

    /// Asks for one WGUIEventType_WindowRedrawRequested, which comes when the display is ready
    /// for the window's next frame: a program that draws whenever it is told to and asks again
    /// runs at the display's pace. Several requests before it is delivered make one event; none
    /// is delivered while the window cannot be seen.
    pub fn wguiWindowRequestRedraw(window: WGUIWindow) -> WGUIStatus;

    /// Shows one of the system's cursors over the window.
    pub fn wguiWindowSetCursorShape(window: WGUIWindow, shape: WGUICursorShape) -> WGUIStatus;

    /// Shows a cursor made with wguiInstanceCreateCursor over the window.
    pub fn wguiWindowSetCustomCursor(window: WGUIWindow, cursor: WGUICursor) -> WGUIStatus;

    /// Shows or hides the cursor while it is over the window.
    pub fn wguiWindowSetCursorVisible(window: WGUIWindow, visible: WGUIBool) -> WGUIStatus;

    /// Keeps the cursor inside the window (Confined), or hides it and reports only movement
    /// (Locked), or lets it go (None). Completes with WGUIEventType_RequestCompleted carrying
    /// `tag`; a later request cancels one still pending.
    ///
    /// A grab is lent, not owned: the user or the system can end it, and
    /// WGUIEventType_WindowCursorGrabChanged reports every change. The host never gives one
    /// kind of grab in place of another.
    pub fn wguiWindowSetCursorGrab(window: WGUIWindow, grab: WGUICursorGrab, tag: u64) -> WGUIStatus;

    /// Moves the cursor to a position in the window. Needs WGUIFeatureName_CursorWarp.
    pub fn wguiWindowSetCursorPosition(window: WGUIWindow, x: f64, y: f64) -> WGUIStatus;

    /// Starts text entry in this window, or updates it (call again whenever the caret moves),
    /// or stops it with NULL. While it is on, input methods and on-screen keyboards work, and
    /// every insertion arrives as WGUIEventType_TextCommit.
    pub fn wguiWindowSetTextInput(window: WGUIWindow, descriptor: *const WGUITextInputDescriptor) -> WGUIStatus;

    /// Throws away the text being composed, as when the program moves its caret itself.
    pub fn wguiWindowResetTextInput(window: WGUIWindow) -> WGUIStatus;

    /// Says which of the embedder's own reactions to input the host should prevent while this
    /// window has it (a browser scrolling the page on a wheel turn or on the space bar, its
    /// context menu). A program polls for input and cannot refuse an event in time, so it
    /// states its choice ahead. Hosts without such reactions accept and ignore it.
    pub fn wguiWindowSetDefaultActions(window: WGUIWindow, prevented: WGUIDefaultActions) -> WGUIStatus;

    /// Shows a frame the program drew itself: for programs without a GPU
    /// (WGUIFeatureName_PixelPresent). The frame is copied before the call returns, so the
    /// program can draw the next one into the same memory.
    ///
    /// The frame fills the window. One of another size than the window's is scaled to it, which
    /// a program avoids by drawing at the size the last WGUIEventType_WindowResized told.
    /// `damage` lists the rectangles of the frame that differ from the one presented before;
    /// none means all of it. A host may show more than what is listed, never less.
    ///
    /// The call does not wait for the display. A program that animates asks for
    /// wguiWindowRequestRedraw after each frame and draws the next one when
    /// WGUIEventType_WindowRedrawRequested comes, which is once per refresh of the display;
    /// frames presented faster than they can be shown replace each other. A window is drawn
    /// this way or through a WebGPU surface, not both.
    pub fn wguiWindowPresentPixels(window: WGUIWindow, frame: *const WGUIPixelFrame, damageCount: usize, damage: *const WGUIRect) -> WGUIStatus;

    // WGUICursor

    /// Destroys the cursor. Windows showing it go back to the default cursor.
    pub fn wguiCursorDestroy(cursor: WGUICursor);
}

// -- Reading events -------------------------------------------------------

/// The first record in a buffer that wguiInstancePollEvents filled with `written` bytes, or
/// null when there is none.
///
/// # Safety
///
/// `buffer` has to be valid for reads of `written` bytes and aligned for a record.
pub unsafe fn wguiEventFirst(buffer: *const u8, written: usize) -> *const WGUIEventHeader {
    let event = buffer.cast::<WGUIEventHeader>();
    if written < size_of::<WGUIEventHeader>() {
        return core::ptr::null();
    }
    let size = (*event).size as usize;
    if size < size_of::<WGUIEventHeader>() || size > written {
        return core::ptr::null();
    }
    event
}

/// The record after `event` in the same buffer, or null at the end.
///
/// # Safety
///
/// As for wguiEventFirst, and `event` has to be a record of that buffer.
pub unsafe fn wguiEventNext(buffer: *const u8, written: usize, event: *const WGUIEventHeader) -> *const WGUIEventHeader {
    let next = (event as usize - buffer as usize) + (*event).size as usize;
    if next >= written {
        return core::ptr::null();
    }
    wguiEventFirst(buffer.add(next), written - next)
}

/// A string of a record. It points into the record: copy it to keep it. An absent string has
/// null data and length 0.
///
/// # Safety
///
/// `event` has to point to a whole record.
pub unsafe fn wguiEventGetString(event: *const WGUIEventHeader, string: WGUIEventString) -> WGUIStringView {
    let size = (*event).size;
    if string.offset as usize >= size_of::<WGUIEventHeader>()
        && string.offset <= size
        && string.length <= size - string.offset
    {
        WGUIStringView {
            data: event.cast::<u8>().add(string.offset as usize),
            length: string.length as usize,
        }
    } else {
        WGUIStringView { data: core::ptr::null(), length: 0 }
    }
}

